package com.bank.flink.dedup;

import java.math.BigDecimal;

// A transaction carrying a stable unique id used as the dedup key.
class Txn {
    private final String txnId;     // the deduplication key
    private final String accountId;
    private final BigDecimal amount;
    private final long eventTimeMillis;

    Txn(String txnId, String accountId, BigDecimal amount, long eventTimeMillis) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getTxnId() { return txnId; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getEventTimeMillis() { return eventTimeMillis; }
}
