package com.bank.flink.dedup;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Models a DataStream KeyedProcessFunction deduplicator: keyed "seen" state
// per txn_id with a TTL, so duplicates are dropped and state stays bounded.
class Deduplicator {
    private static final Logger log = Logger.getLogger(Deduplicator.class.getName());
    private final long ttlMillis;

    // seen txn_id -> expiry time (keyed state + timer analogue)
    private final Map<String, Long> seenUntil = new HashMap<>();

    Deduplicator(long ttlMillis) { this.ttlMillis = ttlMillis; }

    // First call clock-expiry cleanup, then decide: emit (first) or drop (dup).
    boolean accept(Txn t) {
        expire(t.getEventTimeMillis());   // onTimer analogue: clear expired keys
        if (seenUntil.containsKey(t.getTxnId())) {
            log.warning(() -> "DROP duplicate txn_id=" + t.getTxnId());
            return false;
        }
        seenUntil.put(t.getTxnId(), t.getEventTimeMillis() + ttlMillis);
        log.info(() -> "EMIT first txn_id=" + t.getTxnId() + " amount=" + t.getAmount());
        return true;
    }

    // Clear keys whose TTL has passed (bounds state).
    private void expire(long now) {
        seenUntil.entrySet().removeIf(e -> {
            boolean expired = e.getValue() <= now;
            if (expired) log.fine(() -> "TTL expire txn_id=" + e.getKey());
            return expired;
        });
    }

    int stateSize() { return seenUntil.size(); }
}
