package com.bank.flink.dedup;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DeduplicationDemo {
    private static final Logger log = Logger.getLogger(DeduplicationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long min = 60L * 1000;
        // TTL of 10 minutes: catch realistic retries, then forget.
        Deduplicator dedup = new Deduplicator(10 * min);

        // Legitimate transaction.
        log.info("accepted=" + dedup.accept(new Txn("TXN-1", "SAV2001", new BigDecimal("50000"), 0)));
        // Immediate retry duplicate of TXN-1 (same id) -> dropped.
        log.info("accepted=" + dedup.accept(new Txn("TXN-1", "SAV2001", new BigDecimal("50000"), 30 * 1000)));
        // A different transaction.
        log.info("accepted=" + dedup.accept(new Txn("TXN-2", "CUR3001", new BigDecimal("12000"), 1 * min)));
        // CDC-restart re-delivery of TXN-1 at 5 min (still within TTL) -> dropped.
        log.info("accepted=" + dedup.accept(new Txn("TXN-1", "SAV2001", new BigDecimal("50000"), 5 * min)));
        // Much later event with TXN-1 id AFTER TTL (15 min) -> treated as new.
        log.info("accepted=" + dedup.accept(new Txn("TXN-1", "SAV2001", new BigDecimal("50000"), 15 * min)));

        log.info("final dedup state size = " + dedup.stateSize());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
